for (let i = 1; i < meetings.length; i++) {
  const [prevName, , prevEnd] = meetings[i - 1];
  const [name, start] = meetings[i];
  if (start < prevEnd) {
    console.log(`clash: ${prevName} and ${name}`);
    clashes++;
  }
}
if (clashes === 0) {
  console.log("no clashes");
}

