const input = require("fs").readFileSync(0, "utf8");
const bookings = input.trim().split("\n").map((line) => {
  const [name, start, end] = line.trim().split(/\s+/);
  return [name, Number(start), Number(end)];
});

bookings.sort((a, b) => a[1] - b[1] || b[2] - a[2]);

for (const [name, start, end] of bookings) {
  console.log(`${start}-${end} ${name}`);
}

let latestEnd = bookings[0][2];
let gaps = 0;
for (let i = 1; i < bookings.length; i++) {
  const [, start, end] = bookings[i];
  if (start > latestEnd) {
    console.log(`free ${latestEnd}-${start}`);
    gaps++;
  }
  latestEnd = Math.max(latestEnd, end);
}
if (gaps === 0) {
  console.log("fully booked");
}

steps.body:
Objects sort the same way: the comparator reads a field from each one. Numbers subtract, and strings use `localeCompare`, since `"b" - "a"` is `NaN`:

```javascript
const players = [
  { name: "cy", score: 90 },
  { name: "ann", score: 95 },
  { name: "bo", score: 90 },
];
players.sort((a, b) => b.score - a.score || a.name.localeCompare(b.name));
console.log(players.map((p) => `${p.name} ${p.score}`).join(", ")); // ann 95, bo 90, cy 90
```

A Map has no `sort`, so spread it into an array of `[key, value]` pairs first. Then the value is column 1 and the key is column 0:

```javascript harness
const counts = new Map([["red", 2], ["blue", 3], ["green", 2]]);
{{code}}
console.log(JSON.stringify(ranked));
```

```javascript
const ranked = [...counts].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
```

`ranked.slice(0, k)` then gives the top `k`. Use `toSorted` instead of `sort` when you still need the original order afterwards.

**The gotcha:** a comparator must return a number. `(a, b) => a.score > b.score` returns `true` or `false`, and `false` reads as a tie, so the order comes out wrong without any error.

