const input = require("fs").readFileSync(0, "utf8");
const results = input.trim().split("\n").map((line) => {
  const [name, points] = line.trim().split(/\s+/);
  return [name, Number(points)];
});

const totals = new Map();
for (const [name, points] of results) {
  totals.set(name, (totals.get(name) ?? 0) + points);
}
const players = [...totals].map(([name, total]) => ({ name, total }));
players.sort((a, b) => b.total - a.total || a.name.localeCompare(b.name));

players.forEach((p, i) => console.log(`${i + 1}. ${p.name} ${p.total}`));

steps.body:
Some orders are neither numeric nor alphabetical: `high` before `medium` before `low`, or spades before hearts. Give each value its place in a Map, then compare the places:

```javascript
const rank = new Map([["high", 0], ["medium", 1], ["low", 2]]);
const levels = ["low", "high", "medium", "high"];
levels.sort((a, b) => rank.get(a) - rank.get(b));
console.log(levels.join(" ")); // high high medium low
```

The same idea works for any computed key: write a small function that turns an item into a number, and compare those numbers. Points by distance from the origin compare their squared distances, with no square root needed:

```javascript
const dist2 = ([x, y]) => x * x + y * y;
const points = [[3, 4], [1, 1], [0, -2]];
points.sort((p, q) => dist2(p) - dist2(q));
console.log(JSON.stringify(points)); // [[1,1],[0,-2],[3,4]]
```

Chain more rules with `||` as before, most important first. Sorting is stable, so items that tie on every rule keep their input order.

**The gotcha:** a value missing from the rank Map gives `undefined`, and `undefined - 1` is `NaN`, which breaks the sort silently. Make sure every possible value has a rank.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const tasks = input.trim().split("\n").map((line) => {
  const [priority, day, ...words] = line.trim().split(" ");
  return { priority, day: Number(day), name: words.join(" ") };
});

const rank = new Map([["high", 0], ["medium", 1], ["low", 2]]);
tasks.sort(
  (a, b) =>
    rank.get(a.priority) - rank.get(b.priority) ||
    a.day - b.day ||
    a.name.localeCompare(b.name)
);

for (const t of tasks) {
  console.log(`[${t.priority}] day ${t.day}: ${t.name}`);
}

