const input = require("fs").readFileSync(0, "utf8");
const cards = input.trim().split(/\s+/);

const faceValue = new Map([["J", 11], ["Q", 12], ["K", 13], ["A", 14]]);
const suitRank = new Map([["S", 0], ["H", 1], ["D", 2], ["C", 3]]);
const value = (card) => {
  const rank = card.slice(0, -1);
  return faceValue.get(rank) ?? Number(rank);
};

cards.sort(
  (a, b) => suitRank.get(a.at(-1)) - suitRank.get(b.at(-1)) || value(b) - value(a)
);

console.log(cards.join(" "));
